    ('ಅಡುಗೆ ಮಾಡಿದವಳಿಗಿಂತ ಬಡಿಸಿದವಳೇ ಮೇಲು', 'Aduge maadidavaligimta badisidavalee meelu', '[Translation in progress] Traditional folk wisdom: "ಅಡುಗೆ ಮಾಡಿದವಳಿಗಿಂತ ಬಡಿಸಿದವಳೇ ಮೇಲು". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಅಡುಗೆ ಮಾಡಿದವಳಿಗಿಂತ ಬಡಿಸಿದವಳೇ ಮೇಲು". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಅಡುಗೆ","ಮಾಡಿದವಳಿಗಿಂತ","ಬಡಿಸಿದವಳೇ","ಮೇಲು","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಕಿರುಗೂರಿಗೆ ಹೋದರಂತೆ ಕಣಿ ಕೇಳುವುದಕ್ಕೆ', 'Kirugoorige hoodaramte kani keeluvudakke', '[Translation in progress] Traditional folk wisdom: "ಕಿರುಗೂರಿಗೆ ಹೋದರಂತೆ ಕಣಿ ಕೇಳುವುದಕ್ಕೆ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಕಿರುಗೂರಿಗೆ ಹೋದರಂತೆ ಕಣಿ ಕೇಳುವುದಕ್ಕೆ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಕಿರುಗೂರಿಗೆ","ಹೋದರಂತೆ","ಕಣಿ","ಕೇಳುವುದಕ್ಕೆ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಉದ್ದುದ್ದ ಮಾತಿನವರ ಮೊಳಕೈ ಮೊಂಡ', 'Uddudda maatinavara molakai momda', '[Translation in progress] Traditional folk wisdom: "ಉದ್ದುದ್ದ ಮಾತಿನವರ ಮೊಳಕೈ ಮೊಂಡ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಉದ್ದುದ್ದ ಮಾತಿನವರ ಮೊಳಕೈ ಮೊಂಡ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಉದ್ದುದ್ದ","ಮಾತಿನವರ","ಮೊಳಕೈ","ಮೊಂಡ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಕುರು ಮೇಲೆ ಬರೆ ಎಳೆದ ಹಾಗೆ', 'Kuru meele bare eleda haage', '[Translation in progress] Traditional folk wisdom: "ಕುರು ಮೇಲೆ ಬರೆ ಎಳೆದ ಹಾಗೆ". Context: Guidance on education and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಕುರು ಮೇಲೆ ಬರೆ ಎಳೆದ ಹಾಗೆ". ಇದು ಶಿಕ್ಷಣ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'education', 'ಶಿಕ್ಷಣ', 'Used in daily conversations to illustrate education principles and life lessons.', 'ಶಿಕ್ಷಣ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಕುರು","ಮೇಲೆ","ಬರೆ","ಎಳೆದ","ಹಾಗೆ","ಶಿಕ್ಷಣ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಪ್ರೇಮಿಗಳಿಲ್ಲದ ನಾಡು ಬರೀ ಶೂನ್ಯದ ಬೀಡು', 'Preemigalillada naadu baree shoonyada beedu', '[Translation in progress] Traditional folk wisdom: "ಪ್ರೇಮಿಗಳಿಲ್ಲದ ನಾಡು ಬರೀ ಶೂನ್ಯದ ಬೀಡು". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಪ್ರೇಮಿಗಳಿಲ್ಲದ ನಾಡು ಬರೀ ಶೂನ್ಯದ ಬೀಡು". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಪ್ರೇಮಿಗಳಿಲ್ಲದ","ನಾಡು","ಬರೀ","ಶೂನ್ಯದ","ಬೀಡು","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಎತ್ತು ಈಯಿತು ಅಂದರೆ ಕೊಟ್ಟಿಗೆಗೆ ಕಟ್ಟು ಎಂದರಂತೆ', 'Ettu eeyitu amdare kottigege kattu emdaramte', '[Translation in progress] Traditional folk wisdom: "ಎತ್ತು ಈಯಿತು ಅಂದರೆ ಕೊಟ್ಟಿಗೆಗೆ ಕಟ್ಟು ಎಂದರಂತೆ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಎತ್ತು ಈಯಿತು ಅಂದರೆ ಕೊಟ್ಟಿಗೆಗೆ ಕಟ್ಟು ಎಂದರಂತೆ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಎತ್ತು","ಈಯಿತು","ಅಂದರೆ","ಕೊಟ್ಟಿಗೆಗೆ","ಕಟ್ಟು","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಊರು ಸುಟ್ಟರೂ ಹನುಮಂತರಾಯ ಹೊರಗೆ', 'Ooru suttaroo hanumamtaraaya horage', '[Translation in progress] Traditional folk wisdom: "ಊರು ಸುಟ್ಟರೂ ಹನುಮಂತರಾಯ ಹೊರಗೆ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಊರು ಸುಟ್ಟರೂ ಹನುಮಂತರಾಯ ಹೊರಗೆ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಊರು","ಸುಟ್ಟರೂ","ಹನುಮಂತರಾಯ","ಹೊರಗೆ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಮಂಗನ ಕೈಗೆ ಮಾಣಿಕ್ಯ ಕೊಟ್ಟ ಹಾಗೆ', 'Mamgana kaige maanikya kotta haage', '[Translation in progress] Traditional folk wisdom: "ಮಂಗನ ಕೈಗೆ ಮಾಣಿಕ್ಯ ಕೊಟ್ಟ ಹಾಗೆ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಮಂಗನ ಕೈಗೆ ಮಾಣಿಕ್ಯ ಕೊಟ್ಟ ಹಾಗೆ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಮಂಗನ","ಕೈಗೆ","ಮಾಣಿಕ್ಯ","ಕೊಟ್ಟ","ಹಾಗೆ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಹಟ್ಟಿ ತುಂಬಾ ಹಸು, ಹಾಲು ಮಾತ್ರ ತುಸು', 'Hatti tumbaa hasu, haalu maatra tusu', '[Translation in progress] Traditional folk wisdom: "ಹಟ್ಟಿ ತುಂಬಾ ಹಸು, ಹಾಲು ಮಾತ್ರ ತುಸು". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಹಟ್ಟಿ ತುಂಬಾ ಹಸು, ಹಾಲು ಮಾತ್ರ ತುಸು". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಹಟ್ಟಿ","ತುಂಬಾ","ಹಸು","ಹಾಲು","ಮಾತ್ರ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ತಲೇ ಮೇಲಣ ಬರಹ ಎಲೆಯಿಂದ ಒರೆಸಿದರೆ ಹೋದೀತೇ', 'Talee meelana baraha eleyimda oresidare hoodeetee', '[Translation in progress] Traditional folk wisdom: "ತಲೇ ಮೇಲಣ ಬರಹ ಎಲೆಯಿಂದ ಒರೆಸಿದರೆ ಹೋದೀತೇ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ತಲೇ ಮೇಲಣ ಬರಹ ಎಲೆಯಿಂದ ಒರೆಸಿದರೆ ಹೋದೀತೇ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ತಲೇ","ಮೇಲಣ","ಬರಹ","ಎಲೆಯಿಂದ","ಒರೆಸಿದರೆ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಮಾತು ಆಡಿದರೆ ಮುತ್ತಿನ ಹಾರದಂತಿರಬೇಕು', 'Maatu aadidare muttina haaradamtirabeeku', '[Translation in progress] Traditional folk wisdom: "ಮಾತು ಆಡಿದರೆ ಮುತ್ತಿನ ಹಾರದಂತಿರಬೇಕು". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಮಾತು ಆಡಿದರೆ ಮುತ್ತಿನ ಹಾರದಂತಿರಬೇಕು". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಮಾತು","ಆಡಿದರೆ","ಮುತ್ತಿನ","ಹಾರದಂತಿರಬೇಕು","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
